sealed interface Message { val key: String
    data class Order(override val key: String) : Message
    data class Ping(override val key: String) : Message }

private val rules = MutableStateFlow<Map<String, suspend (Message) -> Unit>>(initial)

suspend fun route(m: Message) {
    val table = rules.value                      // one snapshot per message
    (table[m.key] ?: ::deadLetter)(m)
}
fun publish(next: Map<String, suspend (Message) -> Unit>) { rules.update { next } }
